package com.muthumol.player.dummy;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import org.json.*;import java.net.*;import java.io.*;import java.util.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=25)
public class ArtworkTest {
 static byte[] resource(String name)throws Exception{try(InputStream in=ArtworkTest.class.getResourceAsStream("/artwork/"+name)){assertNotNull(name,in);return in.readAllBytes();}}
 @Test public void filenameParserStripsReleaseTagsAndKeepsSeriesEpisode(){MediaTitle f=MediaTitle.parse("[CV] Baahubali.The.Beginning.(2015).Tamil.HDRip.1080p.x264.AAC.mkv");assertEquals("Baahubali The Beginning",f.name);assertEquals(2015,f.year);MediaTitle ep=MediaTitle.parse("Breaking.Bad.S01E02.Cats.in.the.Bag.1080p.WEB-DL.mkv");assertEquals("Breaking Bad",ep.name);assertEquals(1,ep.season);assertEquals(2,ep.episode);assertEquals("Cats in the Bag",ep.episodeName);assertEquals(3,MediaTitle.parse("The.Show.2x03.720p.mkv").episode);}
 @Test public void realMovieResponseMatchesTitleAndYearButRejectsWrongFilm()throws Exception{JSONObject response=new JSONObject(new String(resource("film.json"),"UTF-8"));JSONObject chosen=ArtworkStore.pickFilm(MediaTitle.parse("Baahubali The Beginning (2015).mkv"),response);assertNotNull(chosen);assertEquals("Wikipedia",chosen.getString("source"));assertFalse(chosen.getString("page").contains("soundtrack"));JSONArray pages=response.getJSONObject("query").getJSONArray("pages");JSONObject first=pages.getJSONObject(0);pages.put(0,pages.getJSONObject(1));pages.put(1,first);assertFalse(ArtworkStore.pickFilm(MediaTitle.parse("Baahubali The Beginning (2015).mkv"),response).getString("page").contains("soundtrack"));assertNull(ArtworkStore.pickFilm(MediaTitle.parse("Unrelated Film (2015).mkv"),response));assertNull(ArtworkStore.pickFilm(MediaTitle.parse("Baahubali The Beginning (2026).mkv"),response));}
 @Test public void seriesUsesPromotionalCoverAndEpisodesShareOneDownload()throws Exception{final List<String> urls=new ArrayList<>();ArtworkStore store=new ArtworkStore(RuntimeEnvironment.getApplication(),Runnable::run,(url,cap)->{urls.add(url);if(url.contains("search/shows"))return resource("shows.json");if(url.contains("episode"))throw new AssertionError("Episode scenes must never be requested");return resource("series-cover.jpg");});Movie m=new Movie();m.title="Breaking.Bad.S01E01.1080p.mkv";store.active(true);store.request(m);ArtworkStore.Entry result=store.cached(m);assertNotNull(result);assertEquals("series cover",result.kind);assertTrue(new File(result.path).length()>0);int calls=urls.size();Movie second=new Movie();second.title="Breaking.Bad.S01E02.1080p.mkv";store.request(second);assertEquals(calls,urls.size());assertEquals(result.path,store.cached(second).path);assertEquals(2,calls);}
 @Test public void missingSeriesCoverNeverFallsBackToEpisodeScene()throws Exception{ArtworkStore store=new ArtworkStore(RuntimeEnvironment.getApplication(),Runnable::run,(url,cap)->{if(!url.contains("search/shows"))throw new AssertionError("No episode request");JSONArray shows=new JSONArray(new String(resource("shows.json"),"UTF-8"));for(int i=0;i<shows.length();i++)shows.getJSONObject(i).getJSONObject("show").put("image",JSONObject.NULL);return shows.toString().getBytes("UTF-8");});assertNull(store.seriesCover(MediaTitle.parse("Breaking.Bad.S01E01.mkv")));}
 @Test public void cachedEpisodeStillsFromPreviousVersionAreIgnored()throws Exception{ArtworkStore store=new ArtworkStore(RuntimeEnvironment.getApplication(),Runnable::run,(url,cap)->{throw new IOException();});Movie m=new Movie();m.title="Legacy.Series.S01E01.mkv";store.save(ArtworkStore.hash(MediaTitle.parse(m.title).key()),resource("film.jpg"),new JSONObject().put("kind","episode still"));assertNull(store.cached(m));store.save(ArtworkStore.cacheId(MediaTitle.parse(m.title)),resource("film.jpg"),new JSONObject().put("kind","episode still"));assertNull(store.cached(m));}
 @Test public void telegramSceneIsNotUsedWhenNoPromotionalCoverExists(){PosterArtView view=new PosterArtView(RuntimeEnvironment.getApplication());Movie m=new Movie();m.title="Unique Cover Missing (2026).mkv";m.identity="scene-test";m.artworkPath="/telegram/frame.jpg";m.artwork="YWJj";view.show(m,Ui.ACCENT);String key=org.robolectric.util.ReflectionHelpers.getField(view,"key");assertTrue(key.startsWith("empty:"));assertFalse(key.contains("telegram"));}
 @Test public void stoppedHomeDoesNotStartRequestsAndHostRulesRejectForeignOrCleartext()throws Exception{final int[] calls={0};ArtworkStore store=new ArtworkStore(RuntimeEnvironment.getApplication(),Runnable::run,(url,cap)->{calls[0]++;throw new IOException();});Movie m=new Movie();m.title="A movie.mkv";store.request(m);assertEquals(0,calls[0]);for(String url:new String[]{"http://static.tvmaze.com/a.jpg","https://static.tvmaze.com.evil.test/a.jpg","https://localhost/a","https://api.tvmaze.com:8443/a"})assertFalse(ArtworkStore.allowed(new URL(url)));assertTrue(ArtworkStore.allowed(new URL("https://upload.wikimedia.org/wikipedia/en/a.jpg")));}
 @Test public void failedArtworkUsesBackoffInsteadOfRepeatedHomeRequests(){final int[] calls={0};ArtworkStore store=new ArtworkStore(RuntimeEnvironment.getApplication(),Runnable::run,(url,cap)->{calls[0]++;throw new IOException();});Movie m=new Movie();m.title="Unknown Movie (2026).mkv";store.active(true);store.request(m);store.request(m);assertEquals(1,calls[0]);assertNull(store.cached(m));}
 @Test public void glassBackdropBlurIsBoundedAndKeepsSourceIntact(){android.graphics.Bitmap b=android.graphics.Bitmap.createBitmap(96,144,android.graphics.Bitmap.Config.ARGB_8888);b.eraseColor(android.graphics.Color.BLUE);android.graphics.Bitmap soft=PosterArtView.frost(b);assertFalse(b.isRecycled());assertEquals(96,soft.getWidth());assertEquals(144,soft.getHeight());assertEquals(android.graphics.Color.BLUE,soft.getPixel(48,72));b.recycle();soft.recycle();}

}
